function solve({config,state,event}){
  const own=Object.prototype.hasOwnProperty;
  const cp=x=>{if(Array.isArray(x))return x.map(cp);if(x&&typeof x==='object'){let y={};for(const k of Object.keys(x))Object.defineProperty(y,k,{value:cp(x[k]),enumerable:true,writable:true,configurable:true});return y}return x};
  const eq=(a,b)=>{if(a===b)return true;if(typeof a!==typeof b||a===null||b===null||typeof a!=='object')return false;let ak=Object.keys(a),bk=Object.keys(b);if(ak.length!==bk.length)return false;for(const k of ak)if(!own.call(b,k)||!eq(a[k],b[k]))return false;return true};
  let s=state?{d:cp(state.d),u:cp(state.u),r:cp(state.r),g:cp(state.g),l:state.l}:{d:cp(config.initial),u:[],r:[],g:[],l:config.limit};
  const trim=a=>{while(a.length>s.l)a.shift()};
  const push=(a,x)=>{a.push(cp(x));trim(a)};
  const set=(o,k,v)=>Object.defineProperty(o,k,{value:cp(v),enumerable:true,writable:true,configurable:true});
  const t=event.type;
  if(t==='begin')s.g.push(cp(s.d));
  else if(t==='set'||t==='delete'){
    let n=cp(s.d),ch=false;
    if(t==='set'){ch=!own.call(n,event.key)||!eq(n[event.key],event.value);if(ch)set(n,event.key,event.value)}
    else if(own.call(n,event.key)){ch=true;delete n[event.key]}
    if(ch){if(!s.g.length){push(s.u,s.d);s.r=[]}s.d=n}
  }else if(t==='commit'&&s.g.length){let start=s.g.pop();if(!s.g.length&&!eq(start,s.d)){push(s.u,start);s.r=[]}}
  else if(t==='cancel'&&s.g.length)s.d=s.g.pop();
  else if((t==='undo'||t==='redo')&&!s.g.length){let a=t==='undo'?s.u:s.r,b=t==='undo'?s.r:s.u;if(a.length){let x=a.pop();push(b,s.d);s.d=x}}
  return {state:s,output:{document:cp(s.d),canUndo:!s.g.length&&!!s.u.length,canRedo:!s.g.length&&!!s.r.length,depth:s.g.length}};
}
